  17     if (!validation.success) {
  18       return handleApiError(validation.error);
  19     }
  20 
  21     let { userId, title, body: notificationBody, link } = validation.data;
  22 
  23     // Save notification to Realtime Database as well
  24     let rtdb = admin.database();
  25     let notificationRef = rtdb.ref(`notifications/${userId}`).push();
  26     await notificationRef.set({
  27       title,
  28       description: notificationBody,
  29       icon: 'bell', // A generic icon
  30       isRead: false,
  31       createdAt: new Date().toISOString(),
