  10 interface AuthContextType {
  11   firebaseUser: { uid: string; email: string | null } | null;
  12   userProfile: User | null;
  13   isLoading: boolean;
  14   refetchUser: () => void;
  15 }
  16 
  17 const AuthContext = createContext<AuthContextType | undefined>(undefined);
  18 
  19 export const NextAuthProvider = ({ children }: { children: ReactNode }) => {
  20   const { data: session, status } = useSession();
  21   const queryClient = useQueryClient();
  22   const { setUserProfile } = useBuilderStore();
  23 
  24   // Map NextAuth session to Firebase-like user object for compatibility
  25   const firebaseUser = session?.user ? {
  26     uid: session.user.id,
  27     email: session.user.email,
  28   } : null;
  29 
  30   // Use React Query to get the user profile
  31   const { data: userProfile, isLoading: isProfileLoading } = useQuery<User | null>({
  32     queryKey: userKeys.profile(firebaseUser?.uid ?? ''),
  33     queryFn: async () => {
  34       if (!firebaseUser || !session) return null;
  35       
  36       // Use NextAuth session token instead of Firebase token
  37       const token = session.user.id; // Or use JWT token if needed
  38       const userProfileData = await fetchUserProfileApi(firebaseUser.uid, token);
  39       const userInstance = userProfileData ? new User(userProfileData) : null;
  40       setUserProfile(userInstance);
  41       return userInstance;
  42     },
  43     enabled: !!firebaseUser && !!session,
  44     staleTime: Infinity,
  45   });
  46 
  47   const refetchUser = useCallback(() => {
  48     if (firebaseUser?.uid) {
  49       queryClient.invalidateQueries({ queryKey: userKeys.profile(firebaseUser.uid) });
  50     }
  51   }, [firebaseUser, queryClient]);
  52 
  53   // Update builder store when user profile changes
  54   useEffect(() => {
  55     setUserProfile(userProfile ?? null);
  56   }, [userProfile, setUserProfile]);
  57 
  58   // Clear queries on logout
  59   useEffect(() => {
  60     if (!session) {
  61       queryClient.clear();
  62       setUserProfile(null);
  63     }
  64   }, [session, queryClient, setUserProfile]);
  65 
  66   const isLoading = status === 'loading' || (!!firebaseUser && isProfileLoading);
  67 
  68   return (
  69     <AuthContext.Provider value={{
  70       firebaseUser,
  71       userProfile: userProfile ?? null,
  72       isLoading,
  73       refetchUser
  74     }}>
  75       {children}
  76     </AuthContext.Provider>
  77   );
  78 };
  79 
  80 export const useAuth = (): AuthContextType => {
  81   const context = useContext(AuthContext);
  82   if (context === undefined) {
  83     throw new Error('useAuth must be used within a NextAuthProvider');
  84   }
  85   return context;
  86 };
